import { Col, Icon, Row, Switch } from 'antd'
import styled from 'styled-components'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import ButtonWithPermission from '../../../components/ButtonWithPermission'
import { TitleSpan } from '../../BoradcastCenter/container/index.style'

const SwitchStyleWrapper = styled.div`
  .border-radius-100 {
    border-radius: 100px;
  }
`

export const TABLE_FIELDS = {
  IS_INTERNAL: 'is_internal',
  NAME: 'name',
  CREATED_AT: 'created_at',
  SIZE: 'size'
}

export const FILTER_VALUES = {
  [TABLE_FIELDS.IS_INTERNAL]: {
    INTERNAL: 'internal',
    EXTERNAL: 'external'
  }
}

export const FILTER_OPTIONS = {
  [TABLE_FIELDS.IS_INTERNAL]: [
    { text: 'Test', value: FILTER_VALUES[TABLE_FIELDS.IS_INTERNAL].INTERNAL },
    { text: 'Real', value: FILTER_VALUES[TABLE_FIELDS.IS_INTERNAL].EXTERNAL }
  ]
}

export const getFiltersFields = ({ prePackageOptions }) => {
  return [
    {
      type: 'text',
      name: 'company_name',
      label: 'Company Name'
    },
    {
      type: 'date-range',
      name: 'published-at',
      label: 'Status updated date: ',
      startKey: 'updated_at_start_date',
      endKey: 'updated_at_end_date'
    },
    {
      type: 'select',
      name: 'pre_package_type',
      label: 'SME Prepackage',
      options: Array.isArray(prePackageOptions) ? prePackageOptions : []
    },
    {
      type: 'select',
      name: 'is_internal',
      label: 'Lead Type',
      options: [
        { name: 'Real', code: 'false' },
        { name: 'Testing', code: 'true' }
      ],
      initialValue: 'false'
    }
  ]
}

export const SMEColumns = ({
  goToSMEDetail,
  goToCreateCompany,
  config,
  sortedInfo,
  handleToggleInternalExternal
}) => {
  return [
    {
      title: 'No',
      dataIndex: 'id',
      key: 1
    },
    {
      title: 'Submitted Date',
      dataIndex: 'verification_date',
      render: (verificationAt) => <TitleSpan>{verificationAt}</TitleSpan>,
      width: 200,
      key: 2,
      sorter: () => {},
      sortOrder: sortedInfo.columnKey === 2 && sortedInfo.order
    },
    {
      title: 'Name of user',
      dataIndex: 'name',
      render: (user) => <TitleSpan>{user}</TitleSpan>,
      width: 220,
      key: 3
    },
    {
      title: 'Company Name',
      dataIndex: 'company_name',
      render: (companyName) => <TitleSpan>{companyName}</TitleSpan>,
      width: 220,
      key: 4
    },
    {
      title: 'Email',
      dataIndex: 'work_email',
      render: (email) => <TitleSpan>{email}</TitleSpan>,
      width: 250,
      key: 5
    },
    {
      title: 'Phone',
      dataIndex: 'phone',
      width: 250,
      key: 6
    },
    {
      title: 'SME Prepackage',
      dataIndex: 'sme_prepackage',
      width: 150,
      render: (prePackage) => config?.pre_package_types?.find(({ code }) => code === prePackage)?.name,
      key: 7
    },

    {
      title: 'Status',
      dataIndex: 'lead_status',
      render: (status) => (
        <TitleSpan>
          {
            config?.lead_status?.find(({ code }) => code === status)?.name
          }
        </TitleSpan>
      ),
      width: 150,
      key: 8
    },
    {
      title: 'Status Updated At',
      dataIndex: 'lead_status_updated_at',
      render: (updatedAt) => <TitleSpan>{updatedAt}</TitleSpan>,
      width: 200,
      key: 9,
      sorter: () => {},
      sortOrder: sortedInfo.columnKey === 9 && sortedInfo.order
    },
    {
      title: 'Who\'s update?',
      dataIndex: 'updated_by',
      render: (who) => <TitleSpan>{who}</TitleSpan>,
      width: 190,
      key: 10
    },
    {
      title: 'See Detail',
      render: (rowData) => (
        <>
          <ButtonWithPermission
            type='link'
            onClick={() => {
              goToSMEDetail(rowData)
            }}
            requiredPermission='ops.eb_view_lead_detail'
          >
            View Details <Icon type='eye' />
          </ButtonWithPermission>
        </>
      ),
      width: 190,
      key: 11
    },
    {
      title: 'Notes',
      dataIndex: 'internal_remarks',
      width: 190,
      key: 12
    },
    {
      title: 'Action Button',
      width: 190,
      render: (rowData) => {
        return (
          <>
            {
              rowData.lead_status === 'WINNING' && (
                <Row>
                  <Col span={13}>
                    <ButtonWithPermission
                      type='primary'
                      className='ant-btn ant-btn-primary'
                      ghost
                      onClick={() => {
                        goToCreateCompany(rowData)
                      }}
                      requiredPermission='ops.eb_update_lead'
                      disabled={rowData.is_company_created}
                    >
                      Create Company
                    </ButtonWithPermission>
                  </Col>
                </Row>
              )
            }
          </>
        )
      },
      key: 13
    },
    {
      title: 'Lead Type',
      dataIndex: 'is_internal',
      render: (isInternal, rowData) => (
        <PermissionCheckerV2 requiredPermission='ops.eb_update_lead'>
          <SwitchStyleWrapper>
            <Switch
              unCheckedChildren='Test'
              checkedChildren='Real'
              checked={!isInternal}
              size='default'
              className='border-radius-100'
              onChange={(isInternalUpdatedValue) => handleToggleInternalExternal(isInternalUpdatedValue, rowData.reference_id)}
            />
          </SwitchStyleWrapper>
        </PermissionCheckerV2>
      ),
      ellipsis: true
    }
  ]
}
