import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { EbSectionWrapper } from '../../../CommonComponents'
import { Alert, Button, Col, Row, Spin, Table } from 'antd'
import Summary from './Summary'
import { useErrorContextValue, useGet, useLoaderContextValue, usePost, useResetError } from '@pasarpolis/common-react-hooks'
import { smeApiConfigs } from '../apiConfig'
import { getFiltersFields, SMEColumns } from './utility'
import Filters from '../../../components/Filters'
import { isEmpty } from 'lodash'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'

const SMELeadsComponent = ({ history }) => {
  const [smeList, smeListRequest] = useGet(smeApiConfigs.getSMEPosts)
  const [config, configRequest] = useGet(smeApiConfigs.getSMELeadConfig)
  const [summaryList, summaryListRequest] = useGet(smeApiConfigs.getSMESummary)
  const [, updateLeadRequest] = usePost(smeApiConfigs.updateLeadType)
  const [sortedInfo, setSortedInfo] = useState({})

  const [filters, setFilters] = useState({ is_internal: 'false' })
  const [listMetaData, setListMetaData] = useState({})
  const { resetError } = useResetError()

  const [{ SME_LIST_LOADER, SME_SUMMARY_LOADER, UPDATE_LEAD_TYPE_LOADER }] = useLoaderContextValue()
  const [{ UPDATE_LEAD_TYPE_ERROR, updateLeadTypeStatus }] = useErrorContextValue()

  const handleToggleInternalExternal = useCallback((isInternal, referenceId) => {
    updateLeadRequest({
      reference_id: referenceId,
      is_internal: !isInternal
    })
  }, [updateLeadRequest])

  const goToSMEDetail = useCallback(SMEData => {
    history.push(`/employee-benefits/sme-prepackage-leads/${SMEData.id}`)
  }, [history])

  const goToCreateCompany = useCallback((data) => history.push({ pathname: '/employee-benefits/add-company', state: data }), [history])

  const prePackageOptions = useMemo(() => {
    const options = config?.pre_package_types?.map(({ code, name }) => ({ code, name: `${name}` })) || []
    return options
  }, [config])

  useEffect(() => {
    const metaData = smeList?.meta_data
    if (metaData) {
      setListMetaData(metaData)
    }
  }, [smeList])

  const clearSorters = useCallback(() => {
    setSortedInfo({})
    smeListRequest({ ...filters })
  }, [
    setSortedInfo,
    smeListRequest,
    filters
  ])

  const sortQueryParam = useCallback((sortedInfo) => {
    if (isEmpty(sortedInfo)) return {}
    return {
      sort_by: [sortedInfo.field],
      order: sortedInfo.order
    }
  }, [])

  const handleTableChange = (params, f, sorters) => {
    const query = {
      page: params.current,
      per_page: params.pageSize,
      ...sortQueryParam(sorters)
    }
    setSortedInfo(sorters)
    smeListRequest({ ...query, ...filters })
  }
  const columns = useMemo(() => {
    return SMEColumns({ goToSMEDetail, goToCreateCompany, config, sortedInfo, handleToggleInternalExternal })
  }, [
    goToSMEDetail,
    goToCreateCompany,
    config,
    sortedInfo,
    handleToggleInternalExternal
  ])

  const filterFields = useMemo(() => {
    return getFiltersFields({ prePackageOptions })
  }, [prePackageOptions])

  const postListRemapped = useMemo(() => {
    return Array.isArray(smeList?.data) ? smeList.data : []
  }, [smeList])

  useEffect(() => {
    summaryListRequest({ is_internal: 'false' })
    smeListRequest({ is_internal: 'false' })
    configRequest()
  }, [
    summaryListRequest,
    smeListRequest,
    configRequest
  ])

  useEffect(() => {
    if (updateLeadTypeStatus === 'success') {
      smeListRequest({ ...filters })
      summaryListRequest({ ...filters })
      resetError([
        'updateLeadTypeStatus'
      ])
    }
  }, [
    updateLeadTypeStatus,
    smeListRequest,
    summaryListRequest,
    filters,
    resetError
  ])

  const summaryData = useMemo(() => summaryList ? summaryList.data : {}, [summaryList])

  const handleFilter = useCallback((filters) => {
    smeListRequest({
      ...sortQueryParam(sortedInfo),
      ...filters
    })
    summaryListRequest({ ...filters })
  }, [
    sortedInfo,
    sortQueryParam,
    smeListRequest,
    summaryListRequest
  ])

  const firstRowRecords = useMemo(() => ([
    { heading: 'Submission', data: summaryData?.VERIFIED?.count || 0 },
    { heading: 'Follow up to client', data: summaryData?.FOLLOW_UP?.count || 0 },
    { heading: 'On going discussion', data: summaryData?.ONGOING?.count || 0 },
    { heading: 'Gather closing document', data: summaryData?.DOCUMENTS_AWAITED?.count || 0 },
    { heading: 'Closing document received', data: summaryData?.DOCUMENTS_RECIEVED?.count || 0 },
    { heading: 'Sent invoice', data: summaryData?.SENT_INVOICE?.count || 0 }
  ]), [summaryData])

  const secondRowRecords = useMemo(() => ([
    { heading: 'Payment verified', data: summaryData?.PAYMENT_VERIFIED?.count || 0 },
    { heading: 'Losing client', data: summaryData?.LOSING?.count || 0 },
    { heading: 'Winning', data: summaryData?.WINNING?.count || 0 },
    { heading: 'Onboard users', data: summaryData?.ONBOARD_USERS?.count || 0 },
    { heading: 'Done', data: summaryData?.DONE?.count || 0 }
  ]), [summaryData])

  return (
    <div>
      <EbSectionWrapper>
        <Spin spinning={!!(SME_LIST_LOADER || SME_SUMMARY_LOADER || UPDATE_LEAD_TYPE_LOADER)}>
          <h2>Filters</h2>
          <Filters
            fields={filterFields}
            onFilter={setFilters}
            request={handleFilter}
          />
        </Spin>
      </EbSectionWrapper>
      <PermissionCheckerV2 requiredPermission='ops.eb_view_lead_summary'>
        <EbSectionWrapper>
          <Summary heading='Anaytics' firstRowRecords={firstRowRecords} secondRowRecords={secondRowRecords} />
        </EbSectionWrapper>
      </PermissionCheckerV2>
      <EbSectionWrapper>
        <Spin spinning={!!(SME_LIST_LOADER || SME_SUMMARY_LOADER || UPDATE_LEAD_TYPE_LOADER)}>
          {UPDATE_LEAD_TYPE_ERROR && <Alert type='error' message={updateLeadTypeStatus} banner />}
          <Row>
            <Col span={4}>
              <h2>SME Leads</h2>
            </Col>
            <Col span={6}>
              <Button onClick={clearSorters}>
                Clear sorters
              </Button>
            </Col>
          </Row>
          <Table
            dataSource={postListRemapped}
            rowKey={({ id }) => id}
            columns={columns}
            pagination={{
              pageSize: listMetaData.page_size,
              total: listMetaData.total_records,
              current: listMetaData.page
            }}
            onChange={handleTableChange}
            scroll={{ x: true }}
          />
        </Spin>
      </EbSectionWrapper>
    </div>
  )
}
export default SMELeadsComponent
