import React, { useCallback } from 'react'
import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Alert, Col, Row, Spin, Typography } from 'antd'
import { RowWithMargin } from '../../../../CommonComponents'

const { Text } = Typography

const Summary = ({ firstRowRecords, secondRowRecords, heading }) => {
  const [{ SME_SUMMARY_ERROR, smeSummaryStatus }] = useErrorContextValue()
  const [{ SME_SUMMARY_LOADER }] = useLoaderContextValue()

  const renderSummaryRecord = useCallback((heading, data) => (
    <RowWithMargin key={heading}>
      <Col span={12}><Text strong>{heading}</Text> </Col>
      <Col span={12}>{data}</Col>
    </RowWithMargin>
  ), [])

  return (
    <>
      <Spin spinning={!!SME_SUMMARY_LOADER}>
        {SME_SUMMARY_ERROR && <div className='mb-5'><Alert type='error' message={smeSummaryStatus} banner /></div>}
        <Row>
          <Col><h2>{heading}</h2></Col>
        </Row>
        <Row gutter={64}>
          <Col span={12}>
            {
              firstRowRecords
                .map(({ heading, data }) => renderSummaryRecord(heading, data))
            }
          </Col>
          <Col span={12}>
            {
              secondRowRecords
                .map(({ heading, data }) => renderSummaryRecord(heading, data))
            }
          </Col>
        </Row>
      </Spin>
    </>
  )
}
export default Summary
