import { Form, Input } from 'antd'

const TextFilter = ({ name, label, placeholder, maxLength, getFieldDecorator }) => {
  return (
    <Form.Item label={label} labelAlign='left'>
      {
        getFieldDecorator(name, {})(
          <Input maxLength={maxLength} placeholder={placeholder} allowClear />
        )
      }
    </Form.Item>
  )
}
export default TextFilter
