import { Button } from 'antd'
import { connect } from 'react-redux'

const ButtonWithPermission = ({ permissions, requiredPermission, disabled, ...props }) => {
  const isDisabled = !(Array.isArray(permissions) && permissions.includes(requiredPermission))
  return (
    <Button {...props} disabled={!!(isDisabled || disabled)} />
  )
}
export default connect(
  state => ({
    permissions: state.Auth.permissions
  }),
  {}
)(ButtonWithPermission)
